import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Confronto fra capitalizzazione lineare e composta","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/n_matematica-finanziaria-ed-attuariale/nb/nbae.md","filePath":"lezioni/n_matematica-finanziaria-ed-attuariale/nb/nbae.md"}`),a={name:`lezioni/n_matematica-finanziaria-ed-attuariale/nb/nbae.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="confronto-fra-capitalizzazione-lineare-e-composta" tabindex="-1">Confronto fra capitalizzazione lineare e composta <a class="header-anchor" href="#confronto-fra-capitalizzazione-lineare-e-composta" aria-label="Permalink to “Confronto fra capitalizzazione lineare e composta”">​</a></h1><p>Considero i grafici della capitalizzazione lineare e composta.</p><p><strong>Capitalizzazione lineare</strong></p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mi>M</mi><mo>=</mo><mi>C</mi><mo stretchy="false">(</mo><mn>1</mn><mo>+</mo><mi>i</mi><mi>t</mi><mo stretchy="false">)</mo></mrow><annotation encoding="application/x-tex">M = C(1 + it) </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">M</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0715em;">C</span><span class="mopen">(</span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">i</span><span class="mord mathnormal">t</span><span class="mclose">)</span></span></span></span></span></p><p><strong>Capitalizzazione composta</strong></p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mi>M</mi><mo>=</mo><mi>C</mi><mo stretchy="false">(</mo><mn>1</mn><mo>+</mo><mi>i</mi><msup><mo stretchy="false">)</mo><mi>t</mi></msup></mrow><annotation encoding="application/x-tex">M = C(1 + i)^t </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">M</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0715em;">C</span><span class="mopen">(</span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:1.0936em;vertical-align:-0.25em;"></span><span class="mord mathnormal">i</span><span class="mclose"><span class="mclose">)</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8436em;"><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="katex-sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span></span></span></span></span></span></span></span></span></p><p>Per vedere meglio come si comportano i grafici, la capitalizzazione composta ha un grafico piuttosto &quot;accentuato&quot; come curvatura.</p><p>Ora li metto a confronto ed ottengo:</p><p>Come vediamo dal grafico, per periodi inferiori ad un anno il grafico del montante ad interesse semplice è superiore al grafico del montante ad interesse composto; allo scadere dell&#39;anno i due montanti hanno lo stesso valore; poi, proseguendo, il montante ad interesse composto cresce più del montante ad interesse semplice. Si dice che:</p><ul><li>il montante ad interesse composto cresce in forma esponenziale</li><li>il montante ad interesse semplice cresce in forma lineare (come una retta)</li></ul><blockquote><p><strong>Osservazione:</strong> Vediamo infine cosa significa, per tempi non interi, la capitalizzazione composta con la forma lineare e con la forma esponenziale.</p><p>Mentre con la forma esponenziale calcoli il valore sulla curva rossa, nella forma lineare sostituisci l&#39;ultimo tratto dell&#39;esponenziale con un segmento e vai a calcolare il valore del montante su tale segmento; quindi avrai sempre che, calcolando il montante con la formula lineare, otterrai un valore superiore rispetto al montante calcolato esponenzialmente.</p><p>Puoi anche dire che l&#39;esponenziale ha la concavità verso l&#39;alto, quindi qualunque segmento di retta fra due suoi punti avrà valori superiori rispetto a quelli della curva (e la frazione di capitalizzazione lineare è un segmento di retta).</p></blockquote>`,11)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};